const submitContact = () => { if (!contactForm.value.name || !/^\S+@\S+\.\S+$/.test(contactForm.value.email) || !contactForm.value.message) { notify('Vui lòng điền tên, email hợp lệ và nội dung cần tư vấn'); return; } contactSending.value = true; const conversationId = Date.now(); const message = { id: conversationId, name: contactForm.value.name, email: contactForm.value.email, subject: contactForm.value.subject, message: contactForm.value.message, status: 'new' }; contactInbox.value.unshift(message); contactThread.value.push({ conversationId, from: 'user', message: message.message, authorName: message.name, updatedAt: new Date().toISOString() }); localStorage.setItem('nexa-contact-inbox', JSON.stringify(contactInbox.value)); localStorage.setItem('nexa-contact-thread', JSON.stringify(contactThread.value)); orderSocket?.emit('contact:message', { conversationId, from: 'user', message: message.message, authorName: message.name, authorEmail: message.email, subject: message.subject, updatedAt: new Date().toISOString() }); window.setTimeout(() => { contactSending.value = false; contactSent.value = true; contactForm.value = { name: '', email: '', phone: '', subject: 'Tư vấn laptop', message: '' }; notify('Tin nhắn đã được ghi nhận, Admin có thể phản hồi trực tiếp'); }, 300); };
window.addEventListener('popstate', () => { route.value = window.location.pathname; });
const applyOrderStatus = (event: { orderId: number | string; status: string }) => { const target = orders.value.find(order => String(order.id) === String(event.orderId)); if (!target) return; target.status = orderStatusLabels[event.status] || event.status; localStorage.setItem('nexa-orders', JSON.stringify(orders.value)); notify(`Đơn ${target.id} đã cập nhật: ${target.status}`); };
const applyPaymentStatus = (event: { orderId: number | string; status: string; transactionReference?: string }) => { const target = orders.value.find(order => String(order.id) === String(event.orderId)); if (!target) return; target.paymentStatus = event.status; target.transactionReference = event.transactionReference || target.transactionReference; localStorage.setItem('nexa-orders', JSON.stringify(orders.value)); notify(`Thanh toán đơn ${target.id}: ${paymentStatusLabels[event.status] || event.status}`); };
const applyInventoryUpdate = (event: { productId: number; stock: number }) => { const adminProduct = adminProducts.value.find(product => product.id === event.productId); if (adminProduct) { adminProduct.stock = event.stock; adminProduct.status = event.stock > 0 ? 'Còn hàng' : 'Hết hàng'; } const product = products.find(item => item.id === event.productId); if (product) { product.stock = event.stock; product.status = event.stock > 0 ? 'Còn hàng' : 'Hết hàng'; } notify(`Tồn kho ${product?.name || 'sản phẩm'} đã cập nhật: ${event.stock}`); };
const appendContactEvent = (event: any) => { const duplicate = contactThread.value.some(item => item.conversationId === event.conversationId && item.from === event.from && item.message === event.message); if (duplicate) return; const nextEvent = { ...event, isRead: event.from === 'admin' ? route.value === '/contact' : true }; contactThread.value.push(nextEvent); if (event.from === 'admin' && role.value === 'user' && !nextEvent.isRead) { unreadMessages.value += 1; localStorage.setItem('nexa-unread-messages', String(unreadMessages.value)); } localStorage.setItem('nexa-contact-thread', JSON.stringify(contactThread.value)); let message = contactInbox.value.find(item => String(item.id) === String(event.conversationId)); if (!message && event.from === 'user') { message = { id: event.conversationId, name: event.authorName || 'Người dùng', email: event.authorEmail || 'Chưa có email', subject: event.subject || 'Trao đổi hỗ trợ', message: event.message, status: 'new', messageStatus: 'unread' }; contactInbox.value.unshift(message); } if (message && event.from === 'admin') { message.adminReply = event.message; message.status = 'in_progress'; message.messageStatus = nextEvent.isRead ? 'read' : 'unread'; } localStorage.setItem('nexa-contact-inbox', JSON.stringify(contactInbox.value)); notify(event.from === 'admin' ? 'Bạn vừa nhận phản hồi từ Admin' : 'Có tin nhắn mới từ người dùng'); };
const updateDemoOrderStatus = (order: any, status: string) => { order.status = orderStatusLabels[status] || status; localStorage.setItem('nexa-orders', JSON.stringify(orders.value)); orderSocket?.emit('admin:order-status', { orderId: order.id, status }); notify(`Đã cập nhật trạng thái ${order.id}`); };
const updateDemoPaymentStatus = (order: any, status: string) => { order.paymentStatus = status; order.transactionReference = status === 'paid' ? `DEMO-${Date.now().toString().slice(-6)}` : order.transactionReference; localStorage.setItem('nexa-orders', JSON.stringify(orders.value)); orderSocket?.emit('admin:payment-status', { orderId: order.id, status, transactionReference: order.transactionReference }); notify(`Đã cập nhật thanh toán ${order.id}`); };
const handleAdminStatusChange = (order: any, event: Event) => { updateDemoOrderStatus(order, (event.target as HTMLSelectElement).value); };
const handleAdminPaymentChange = (order: any, event: Event) => { updateDemoPaymentStatus(order, (event.target as HTMLSelectElement).value); };
const updateInventory = (product: Product) => { product.stock = Math.max(0, Number(product.stock) || 0); product.status = product.stock > 0 ? 'Còn hàng' : 'Hết hàng'; orderSocket?.emit('admin:inventory-updated', { productId: product.id, stock: product.stock }); notify(`Đã cập nhật tồn kho ${product.name}`); };
const showOrderDetail = (order: any) => { selectedOrder.value = order; orderDetailOpen.value = true; };
const orderStatusKey = (status: string) => Object.keys(orderStatusLabels).find(key => orderStatusLabels[key] === status) || (status === 'Đang xử lý' ? 'pending' : status);
const orderProgress = (status: string) => { const key = orderStatusKey(status); return key === 'cancelled' ? -1 : orderStatuses.indexOf(key as typeof orderStatuses[number]); };
onMounted(() => { orderSocket = io(window.location.origin, { path: '/socket.io' }); orderSocket.on('connect', () => orderSocket?.emit('subscribe:orders')); orderSocket.on('order:updated', applyOrderStatus); orderSocket.on('payment:updated', applyPaymentStatus); orderSocket.on('inventory:updated', applyInventoryUpdate); orderSocket.on('contact:message', appendContactEvent); orderSocket.on('contact:reply', appendContactEvent); heroTimer = window.setInterval(() => { heroSlide.value = (heroSlide.value + 1) % heroSlides.length; }, 5000); });
onBeforeUnmount(() => { orderSocket?.disconnect(); orderSocket = null; if (heroTimer) window.clearInterval(heroTimer); });
watch(route, (path) => { if (path.startsWith('/admin') && path !== '/admin/login' && role.value !== 'admin') { route.value = '/admin/login'; window.history.replaceState({}, '', '/admin/login'); } });
const setRole = (next: 'user' | 'admin') => { role.value = next; localStorage.setItem('nexa-role', next); showProfile.value = false; navigate(next === 'admin' ? '/admin/dashboard' : '/'); };
const logoutLocal = () => { role.value = 'user'; localStorage.setItem('nexa-role', 'user'); authEmail.value = ''; authPassword.value = ''; notify('Đã đăng xuất tài khoản'); navigate('/'); };
const toggleFavorite = (product: Product) => { const exists = favorites.value.includes(product.id); favorites.value = exists ? favorites.value.filter(id => id !== product.id) : [...favorites.value, product.id]; localStorage.setItem('nexa-favorites', JSON.stringify(favorites.value)); notify(exists ? 'Đã bỏ khỏi yêu thích' : 'Đã lưu vào yêu thích'); };
const submitLogin = () => {
  const adminLogin = route.value === '/admin/login';
  if (!authEmail.value || !authPassword.value) { authNotice.value = 'Vui lòng nhập email và mật khẩu.'; return; }
  if (adminLogin && authEmail.value === 'admin@nexa.store' && authPassword.value === 'admin123!') { authNotice.value = ''; setRole('admin'); navigate('/admin/dashboard'); return; }
  if (!adminLogin && authEmail.value === 'user@demo.com' && authPassword.value === '123456') { authNotice.value = ''; localStorage.setItem('nexa-user-name', 'Người Dùng Demo'); setRole('user'); navigate('/'); return; }
  if (!adminLogin) { authNotice.value = 'Sai thông tin. Dùng user@demo.com / 123456 để thử tài khoản demo.'; return; }
  authNotice.value = 'Thông tin admin demo chưa đúng. Hãy dùng admin@nexa.store / admin123!';
};
const submitRegister = () => {
  if (!authName.value || !authEmail.value || authPassword.value.length < 8) { authNotice.value = 'Nhập họ tên, email và mật khẩu tối thiểu 8 ký tự.'; return; }
  localStorage.setItem('nexa-demo-user', JSON.stringify({ name: authName.value, email: authEmail.value }));
  authNotice.value = 'Đăng ký thành công. Bạn có thể đăng nhập ngay.';
  navigate('/login');
};
window.setTimeout(() => { catalogLoading.value = false; }, 420);
const persistCart = () => localStorage.setItem('nexa-cart', JSON.stringify(cart.value));
const notify = (message: string) => { toast.value = message; window.setTimeout(() => toast.value = '', 2600); };

const filteredProducts = computed(() => {
  let list = products.filter((item) => {
    const q = search.value.toLowerCase().trim();
    const matchesGroup = (item.group || 'Laptop') === activeCatalogGroup.value;
    const matchesSearch = !q || `${item.name} ${item.brand} ${item.specs.join(' ')}`.toLowerCase().includes(q);
    const matchesCategory = activeCategory.value === 'Tất cả' || item.category === activeCategory.value;
    const matchesBrand = activeBrand.value === 'Tất cả' || item.brand === activeBrand.value;
    const matchesPrice = priceBucket.value === 'Tất cả' || (priceBucket.value === 'under20' && item.price < 20000000) || (priceBucket.value === '20to30' && item.price >= 20000000 && item.price <= 30000000) || (priceBucket.value === 'over30' && item.price > 30000000);
    return matchesGroup && matchesSearch && matchesCategory && matchesBrand && matchesPrice;
  });
  if (sortBy.value === 'Giá thấp') list = [...list].sort((a, b) => a.price - b.price);
  if (sortBy.value === 'Giá cao') list = [...list].sort((a, b) => b.price - a.price);
  if (sortBy.value === 'Đánh giá') list = [...list].sort((a, b) => b.rating - a.rating);
  return list;
});
const pagedProducts = computed(() => filteredProducts.value.slice((page.value - 1) * pageSize, page.value * pageSize));
const pageCount = computed(() => Math.max(1, Math.ceil(filteredProducts.value.length / pageSize)));
const adminFilteredProducts = computed(() => adminProducts.value.filter((item) => `${item.name} ${item.brand} ${item.category}`.toLowerCase().includes(adminSearch.value.toLowerCase())));
const adminTitle = computed(() => ({ products: 'Quản lý sản phẩm', categories: 'Quản lý danh mục', brands: 'Quản lý thương hiệu', inventory: 'Tồn kho', users: 'Người dùng', orders: 'Đơn hàng', contacts: 'Hộp thư liên hệ' } as Record<string, string>)[adminTab.value] || 'Tổng quan vận hành');
watch([search, activeCategory, activeBrand, priceBucket, sortBy], () => { page.value = 1; });
const cartCount = computed(() => cart.value.reduce((sum, item) => sum + item.quantity, 0));
const cartTotal = computed(() => cart.value.reduce((sum, item) => sum + item.price * item.quantity, 0));
const routeProduct = computed(() => { const id = Number(route.value.split('/').pop()); return products.find((item) => item.id === id) || products[0]; });
const activeDetailImage = ref(routeProduct.value.image);
const detailGallery = computed(() => [routeProduct.value.image, 'assets/images/products/product-2.svg', 'assets/images/products/product-4.svg']);
const detailSpecs = computed(() => ({ cpu: routeProduct.value.specs[0] || 'Đang cập nhật', ram: routeProduct.value.specs[1] || 'Đang cập nhật', storage: routeProduct.value.specs[2] || 'Đang cập nhật', gpu: routeProduct.value.specs[2] || 'Đồ họa tích hợp', display: routeProduct.value.specs[3] || 'Đang cập nhật', battery: '70Wh', weight: '1.6kg' }));
watch(routeProduct, product => { activeDetailImage.value = product.image; });
const addToCart = (product: Product, variant?: { id?: number; name?: string; priceAdjustment?: number }) => { if (product.stock <= 0) { notify('Sản phẩm hiện đã hết hàng'); return; } const existing = cart.value.find((item) => item.id === product.id && item.variantId === variant?.id); if (existing) { if (existing.quantity >= product.stock) { notify('Sản phẩm đã đạt giới hạn tồn kho'); return; } existing.quantity += 1; } else cart.value.push({ ...product, price: product.price + (variant?.priceAdjustment || 0), quantity: 1, variantId: variant?.id, variantName: variant?.name }); persistCart(); notify(`${product.name}${variant?.name ? ` · ${variant.name}` : ''} đã được thêm vào giỏ`); };
const updateQty = (id: number, delta: number) => { const item = cart.value.find((line) => line.id === id); if (!item) return; const next = item.quantity + delta; if (next > item.stock) { notify('Không thể vượt quá số lượng tồn kho'); return; } item.quantity = next; if (item.quantity <= 0) cart.value = cart.value.filter((line) => line.id !== id); persistCart(); };
const removeFromCart = (id: number) => { cart.value = cart.value.filter((line) => line.id !== id); persistCart(); };
const shippingFee = computed(() => cartTotal.value >= 5000000 ? 0 : 30000);
const discount = computed(() => checkoutForm.value.coupon.trim().toUpperCase() === 'NEXA10' ? Math.min(500000, Math.round(cartTotal.value * .1)) : 0);
const checkoutTotal = computed(() => cartTotal.value + shippingFee.value - discount.value);
const checkout = () => { if (!cart.value.length) return; checkoutNotice.value = ''; checkoutOpen.value = true; };
const placeOrder = () => { if (!cart.value.length) return; const invalidStock = cart.value.find(item => item.quantity > item.stock); if (invalidStock) { checkoutNotice.value = `${invalidStock.name} không đủ tồn kho cho số lượng đã chọn`; return; } if (!checkoutForm.value.name || !checkoutForm.value.phone || checkoutForm.value.address.length < 10) { checkoutNotice.value = 'Vui lòng nhập đầy đủ người nhận, số điện thoại và địa chỉ giao hàng.'; return; } const orderId = `NX-${Date.now().toString().slice(-6)}`; const paymentMethod = checkoutForm.value.payment === 'cod' ? 'COD' : checkoutForm.value.payment === 'bank' ? 'Chuyển khoản QR' : checkoutForm.value.payment === 'momo' ? 'MoMo' : 'ZaloPay'; const order = { id: orderId, invoiceNumber: `INV-${orderId}`, createdAt: new Date().toLocaleDateString('vi-VN'), items: cart.value.map(({ id, name, quantity, price, variantName }) => ({ id, name: variantName ? `${name} · ${variantName}` : name, quantity, price })), subtotal: cartTotal.value, shippingFee: shippingFee.value, discount: discount.value, tax: 0, total: checkoutTotal.value, recipientName: checkoutForm.value.name, recipientPhone: checkoutForm.value.phone, shippingAddress: checkoutForm.value.address, paymentMethod, paymentStatus: checkoutForm.value.payment === 'cod' ? 'unpaid' : 'pending', status: 'Chờ xác nhận' }; orders.value.unshift(order); localStorage.setItem('nexa-orders', JSON.stringify(orders.value)); cart.value = []; persistCart(); checkoutOpen.value = false; showCart.value = false; checkoutNotice.value = `Đặt hàng thành công · Mã đơn ${order.id}`; checkoutForm.value = { name: '', phone: '', address: '', payment: 'cod', coupon: '' }; notify(`Đặt hàng thành công · ${order.id}`); navigate('/orders'); };
const handleProductImages = (event: Event) => { productImageNames.value = Array.from((event.target as HTMLInputElement).files || []).map(file => file.name); };
const saveProduct = () => { if (!productDraft.value.name.trim()) return; const draft = productDraft.value; const imageCount = productImageNames.value.length || 1; adminProducts.value.unshift({ id: Date.now(), name: draft.name, brand: draft.brand, price: Number(draft.price), rating: 4.7, image: 'assets/images/products/product-1.svg', badge: 'Mới thêm', category: draft.category, description: `${draft.name} được tạo từ khu vực quản trị NEXA với cấu hình có thể mở rộng.`, specs: [draft.cpu, draft.ram, draft.storage, draft.gpu, draft.display], stock: 10, tone: 'ice', group: activeCatalogGroup.value }); showProductForm.value = false; productDraft.value = { name: '', brand: 'Nexa', price: 19990000, category: 'Văn phòng', cpu: 'Intel Core i7-13700H', ram: '16GB DDR5 4800MHz', storage: '512GB PCIe Gen4 SSD', gpu: 'RTX 4060 8GB', display: '15.6 inch FHD 144Hz', battery: '70Wh', weight: '1.8kg' }; productImageNames.value = []; notify(`Đã thêm sản phẩm với ${imageCount} ảnh vào catalog quản trị`); };
const removeAdminProduct = (id: number) => { adminProducts.value = adminProducts.value.filter((item) => item.id !== id); notify('Đã xóa sản phẩm khỏi danh sách demo'); };
const saveCategory = () => { const name = categoryDraft.value.trim(); if (!name) return; adminCategories.value.push({ id: Date.now(), name, products: 0 }); categoryDraft.value = ''; notify('Đã thêm danh mục vào hệ thống demo'); };
const removeCategory = (id: number) => { adminCategories.value = adminCategories.value.filter((item) => item.id !== id); notify('Đã xóa danh mục khỏi hệ thống demo'); };
const markContactRead = (message: any) => { message.status = message.status === 'new' ? 'in_progress' : 'resolved'; localStorage.setItem('nexa-contact-inbox', JSON.stringify(contactInbox.value)); notify(message.status === 'resolved' ? 'Đã đánh dấu yêu cầu đã xử lý' : 'Đã tiếp nhận tin nhắn'); };
const replyContact = (message: any) => { const reply = (contactReplyDraft.value[String(message.id)] || '').trim(); if (!reply) { notify('Hãy viết nội dung phản hồi trước khi gửi'); return; } message.adminReply = reply; message.status = 'in_progress'; contactThread.value.push({ conversationId: message.id, from: 'admin', message: reply, authorName: 'NEXA Admin', updatedAt: new Date().toISOString() }); contactReplyDraft.value[String(message.id)] = ''; localStorage.setItem('nexa-contact-inbox', JSON.stringify(contactInbox.value)); localStorage.setItem('nexa-contact-thread', JSON.stringify(contactThread.value)); orderSocket?.emit('contact:reply', { conversationId: message.id, from: 'admin', message: reply, authorName: 'NEXA Admin', updatedAt: new Date().toISOString() }); notify(`Đã gửi phản hồi tới ${message.email}`); };

const authRoute = computed(() => ['/login', '/register', '/admin/login'].includes(route.value));
const isAdmin = computed(() => route.value.startsWith('/admin') && route.value !== '/admin/login' && role.value === 'admin');
const favoriteProducts = computed(() => products.filter(product => favorites.value.includes(product.id)));
const productPage = computed(() => route.value === '/laptops' || route.value === '/');
const catalogGroupDescription = computed(() => activeCatalogGroup.value === 'Laptop' ? 'Cấu hình cân bằng, trải nghiệm rõ ràng, giá trị dài lâu.' : `Khám phá ${activeCatalogGroup.value.toLowerCase()} được tuyển chọn trong cùng một hệ sinh thái NEXA.`);
</script>

