"pagination"><button :disabled="page === 1" @click="page--"><ChevronLeft :size="17" /></button><button v-for="n in pageCount" :key="n" :class="{ current: page === n }" @click="page = n">{{ n }}</button><button :disabled="page === pageCount" @click="page++"><ChevronRight :size="17" /></button></div></template></div></div></section>

